(* [comment removed for export] *)
Lemma parser_at_pop : forall segs (M M' : word -> option byte) (Sg : Z -> Prop) P ps x stk,
  (forall a, Sg a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  PTA.out Sg P 256 -> PTA.out Sg (P + 264) 8 -> PTA.out Sg (PML.ps_bptr ps) (PML.ps_bcap ps) -> PTA.out Sg (PML.ps_sb ps) (Z.of_nat (length stk)) ->
  PMLA.parser_at segs IC M P ps -> PML.ps_stack ps = stk ++ [x] ->
  L5.u64_at segs M' (P + 256) (PML.ps_sb ps + Z.of_nat (length stk)) ->
